function MaeChaem_Q_H_windows
% Sliding-window Vietoris-Rips complexes.
% Generated by Analysis.py.
% Universal embedding delay: 3 time steps (3 time units).
% Universal connection threshold: 3.1622777.
% Each frame uses 33 raw time steps (30 plus the delay span)
% and advances by 30 time steps.

here = fileparts(mfilename('fullpath'));
S = load(fullfile(here, 'MaeChaem_Q_H_windows.mat'));
frameCount = numel(S.frameStart);
figureHandle = uifigure('Name', 'Sliding-window complex', 'Position', [60 60 1180 640]);
complexAxes = uiaxes(figureHandle, 'Position', [30 90 680 490]);
h0Axes = uiaxes(figureHandle, 'Position', [740 370 400 210]);
h1Axes = uiaxes(figureHandle, 'Position', [740 90 400 240]);
labelHandle = uilabel(figureHandle, 'Position', [30 600 1100 22], ...
    'Text', frameCaption(S, 1));
if frameCount < 2
    showFrame(1);
    return
end
sliderHandle = uislider(figureHandle, 'Position', [30 48 1100 3], ...
    'Limits', [1 frameCount], 'Value', 1, ...
    'MajorTicks', unique([1 round(frameCount / 2) frameCount]));
sliderHandle.ValueChangedFcn = @(~, event) showFrame(round(event.Value));
sliderHandle.ValueChangingFcn = @(~, event) showFrame(round(event.Value));
showFrame(1);

    function showFrame(frameIndex)
        frameIndex = min(max(frameIndex, 1), frameCount);
        labelHandle.Text = frameCaption(S, frameIndex);
        cla(complexAxes);
        hold(complexAxes, 'on');
        points = S.points{frameIndex};
        triangles = S.triangles{frameIndex};
        edges = S.edges{frameIndex};
        if ~isempty(triangles)
            patch(complexAxes, 'Faces', triangles, 'Vertices', points, ...
                'FaceColor', [0.30 0.47 0.66], 'FaceAlpha', 0.35, 'EdgeColor', 'none');
        end
        if ~isempty(edges)
            edgeX = [points(edges(:, 1), 1).'; points(edges(:, 2), 1).'; nan(1, size(edges, 1))];
            edgeY = [points(edges(:, 1), 2).'; points(edges(:, 2), 2).'; nan(1, size(edges, 1))];
            plot(complexAxes, edgeX(:), edgeY(:), 'Color', [0.75 0.22 0.17], 'LineWidth', 1.2);
        end
        if ~isempty(points)
            scatter(complexAxes, points(:, 1), points(:, 2), 18, [0.13 0.13 0.13], 'filled');
        end
        hold(complexAxes, 'off');
        axis(complexAxes, 'equal');
        grid(complexAxes, 'on');
        xlabel(complexAxes, S.coordinateNames{1});
        if numel(S.coordinateNames) > 1
            ylabel(complexAxes, S.coordinateNames{2});
        end
        title(complexAxes, sprintf('delay = %d, threshold = %.6g', S.embeddingDelay, S.threshold));
        drawBarcode(h0Axes, S.h0Intervals{frameIndex}, 'H0 Persistence Barcode');
        drawBarcode(h1Axes, S.h1Intervals{frameIndex}, 'H1 Persistence Barcode');
    end
end

function drawBarcode(axesHandle, intervals, titleText)
cla(axesHandle);
hold(axesHandle, 'on');
title(axesHandle, titleText);
xlabel(axesHandle, 'Filtration value');
if isempty(intervals)
    text(axesHandle, 0.5, 0.5, 'No intervals', 'Units', 'normalized', ...
        'HorizontalAlignment', 'center');
    yticks(axesHandle, []);
    hold(axesHandle, 'off');
    return
end
finiteDeaths = intervals(isfinite(intervals(:, 2)), 2);
if isempty(finiteDeaths)
    rightEdge = max(intervals(:, 1)) + 1;
else
    span = max(finiteDeaths) - min(intervals(:, 1));
    if span <= 0
        span = max(max(finiteDeaths), 1);
    end
    rightEdge = max(finiteDeaths) + 0.1 * span;
end
for row = 1:size(intervals, 1)
    birth = intervals(row, 1);
    death = intervals(row, 2);
    if ~isfinite(death)
        death = rightEdge;
    end
    patch(axesHandle, [birth death death birth], ...
        [row - 0.35 row - 0.35 row + 0.35 row + 0.35], ...
        [0.90 0.40 0.40], 'EdgeColor', 'none', 'FaceAlpha', 0.75);
end
leftEdge = min(intervals(:, 1));
pad = 0.05 * max(rightEdge - leftEdge, 1);
xlim(axesHandle, [leftEdge - pad, rightEdge + pad]);
ylim(axesHandle, [0.4 size(intervals, 1) + 0.6]);
yticks(axesHandle, []);
grid(axesHandle, 'on');
hold(axesHandle, 'off');
end

function caption = frameCaption(S, frameIndex)
caption = sprintf('Frame %d/%d   start %.6g   beta_0 = %g   beta_1 = %g', ...
    frameIndex, numel(S.frameStart), S.frameStart(frameIndex), ...
    S.beta0(frameIndex), S.beta1(frameIndex));
end
